(7407109, 1166980, 124815, '<td valign="top">what a great place and composition - I like the grain but oh, you got too much sharpening especially on the left side of the picture, building and tower.... I wish that you''ll revisit the image and process it differently.</td>', 'what a great place and composition - I like the grain but oh, you got too much sharpening especially on the left side of the picture, building and tower.... I wish that you''ll revisit the image and process it differently.', '2015-10-01 09:21:49.000000', NULL, 1),
(7407110, 1167185, 124815, '<td valign="top">Ha! We were there in the same time. You certainly got a nice view but in my opinion, not the spirit. The colors are uniformly saturated from foreground to background and you missed the gritty part making therefore more of a postcard then your own vision. It''s more like Burano than Venice. Hope you had a great time.</td>', 'Ha! We were there in the same time. You certainly got a nice view but in my opinion, not the spirit. The colors are uniformly saturated from foreground to background and you missed the gritty part making therefore more of a postcard then your own vision. It''s more like Burano than Venice. Hope you had a great time.', '2015-10-01 09:29:03.000000', NULL, 1),
(7407115, 1166794, 73942, '<td valign="top">Fantastic capture</td>', 'Fantastic capture', '2015-10-01 09:56:06.000000', NULL, 1),
