(7407965, 1167235, 30982, '<td valign="top">What a great collection of faces.  So grim.  Like the hand on the left, with the red bag - nice touch.</td>', 'What a great collection of faces.  So grim.  Like the hand on the left, with the red bag - nice touch.', '2015-10-04 23:39:58.000000', NULL, 1),
(7407966, 1167254, 30982, '<td valign="top">Ha!  Yes!  There appears to be a bird on your head!</td>', 'Ha!  Yes!  There appears to be a bird on your head!', '2015-10-04 23:40:10.000000', NULL, 1),
(7407967, 1167310, 30982, '<td valign="top">Someone is doing senior portraits with a unique flare, I''m guessing!</td>', 'Someone is doing senior portraits with a unique flare, I''m guessing!', '2015-10-04 23:40:33.000000', NULL, 1),
(7407969, 1167185, 30982, '<td valign="top">You just can''t miss with these colors - so rich!  And love the raindrops on the water, also very Venice.  Nice touch with the gent on the bridge to add a wee bit of life.</td>', 'You just can''t miss with these colors - so rich!  And love the raindrops on the water, also very Venice.  Nice touch with the gent on the bridge to add a wee bit of life.', '2015-10-04 23:41:06.000000', NULL, 1),
(7407970, 1166827, 30982, '<td valign="top">What a great place this would be to drive.  I suspect it''s not somewhere I can get my car to very easily, though.</td>', 'What a great place this would be to drive.  I suspect it''s not somewhere I can get my car to very easily, though.', '2015-10-04 23:42:12.000000', NULL, 1),
(7407972, 1167234, 30982, '<td valign="top">The expressions on the folks behind the bride are priceless! Great faces all around, including the sinders, and gotta love those flare streaks.  Definitely a keeper and I'' gotta bet the bride LOVES it.</td>', 'The expressions on the folks behind the bride are priceless! Great faces all around, including the sinders, and gotta love those flare streaks.  Definitely a keeper and I'' gotta bet the bride LOVES it.', '2015-10-04 23:42:55.000000', NULL, 1),
(7407973, 1167289, 30982, '<td valign="top">Sweet sparklies!!</td>', 'Sweet sparklies!!', '2015-10-04 23:43:12.000000', NULL, 1),
(7407974, 1166905, 30982, '<td valign="top">The wedge of human energy is fascinating!  Great shot, exceptional processing.</td>', 'The wedge of human energy is fascinating!  Great shot, exceptional processing.', '2015-10-04 23:43:32.000000', NULL, 1),
(7407975, 1167215, 30982, '<td valign="top">Gorgeous light.  So peaceful.</td>', 'Gorgeous light.  So peaceful.', '2015-10-04 23:43:42.000000', NULL, 1),
(7407976, 1166316, 30982, '<td valign="top">I like the reflected selves on the top - gives it an ethereal feel.</td>', 'I like the reflected selves on the top - gives it an ethereal feel.', '2015-10-04 23:44:12.000000', NULL, 1),
(7407977, 1167290, 30982, '<td valign="top">Oh, those eyes!!  And those whiskers - so perfectly curved.  What a cute little gal!</td>', 'Oh, those eyes!!  And those whiskers - so perfectly curved.  What a cute little gal!', '2015-10-04 23:44:32.000000', NULL, 1),
(7407978, 1166241, 30982, '<td valign="top">I think I saw this in a gallery somewhere, didn''t I?</td>', 'I think I saw this in a gallery somewhere, didn''t I?', '2015-10-04 23:44:52.000000', NULL, 1),
(7407980, 1166702, 30982, '<td valign="top">Pure joy!!  Awesome flare.</td>', 'Pure joy!!  Awesome flare.', '2015-10-04 23:45:08.000000', NULL, 1),
(7407981, 1167202, 30982, '<td valign="top">Really lovely in it''s silence.</td>', 'Really lovely in it''s silence.', '2015-10-04 23:45:23.000000', NULL, 1),
(7408119, 1167097, 149964, '<td valign="top">Beautiful image- I love that it looks as though the modern balloons are superimposed on history. One of my favourites.</td>', 'Beautiful image- I love that it looks as though the modern balloons are superimposed on history. One of my favourites.', '2015-10-05 16:51:34.000000', NULL, 1),
(7408120, 1167215, 149964, '<td valign="top">I really love the light on this. I''m not usually a fan of townscapes but definitely making an exception for this.One of my favourites.</td>', 'I really love the light on this. I''m not usually a fan of townscapes but definitely making an exception for this.One of my favourites.', '2015-10-05 16:52:59.000000', NULL, 1),
(7408121, 1167186, 149964, '<td valign="top">Magical!</td>', 'Magical!', '2015-10-05 16:53:28.000000', NULL, 1),
(7408122, 1167185, 149964, '<td valign="top">I love the perspective on this and the gorgeous colours. One of my favourites.</td>', 'I love the perspective on this and the gorgeous colours. One of my favourites.', '2015-10-05 16:54:25.000000', NULL, 1),
(7408123, 1167081, 149964, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2015-10-05 16:55:08.000000', NULL, 1),
(7408124, 1165976, 149964, '<td valign="top">I love the symmetry of this  - and the odd area where this symmetry is broken makes it even more interesting.</td>', 'I love the symmetry of this  - and the odd area where this symmetry is broken makes it even more interesting.', '2015-10-05 16:56:08.000000', NULL, 1),
(7408127, 1166847, 149964, '<td valign="top">Just love the primary red of the boat against the natural colours in the rest of the scene.</td>', 'Just love the primary red of the boat against the natural colours in the rest of the scene.', '2015-10-05 16:57:01.000000', NULL, 1),
(7408128, 1167254, 149964, '<td valign="top">Made me smile!</td>', 'Made me smile!', '2015-10-05 16:57:16.000000', NULL, 1),
(7408129, 1167247, 149964, '<td valign="top">I love the subject of this - grown up an'' all!</td>', 'I love the subject of this - grown up an'' all!', '2015-10-05 16:58:07.000000', NULL, 1),
(7408130, 1166455, 149964, '<td valign="top">I really like how the symmetry of the stairs is broken by the figure at the bottom.</td>', 'I really like how the symmetry of the stairs is broken by the figure at the bottom.', '2015-10-05 16:59:33.000000', NULL, 1),
(7408131, 1166733, 149964, '<td valign="top">I like the way the high rid buildings on the horizon contrast with the low-level green of the foreground.</td>', 'I like the way the high rid buildings on the horizon contrast with the low-level green of the foreground.', '2015-10-05 17:00:32.000000', NULL, 1),
(7408133, 1167310, 149964, '<td valign="top">Lovely sharp image.</td>', 'Lovely sharp image.', '2015-10-05 17:00:57.000000', NULL, 1),
(7408135, 1167261, 149964, '<td valign="top">Really like this although but part of me wonders if a little more focus on mid-range of sunflowers would have made it even better.</td>', 'Really like this although but part of me wonders if a little more focus on mid-range of sunflowers would have made it even better.', '2015-10-05 17:04:52.000000', NULL, 1),
(7408136, 1167202, 149964, '<td valign="top">Really striking capture of urbanity.</td>', 'Really striking capture of urbanity.', '2015-10-05 17:05:38.000000', NULL, 1);
