(7408151, 1167222, 57447, '<td valign="top">Beautiful coastal scene.</td>', 'Beautiful coastal scene.', '2015-10-05 19:02:28.000000', NULL, 1),
(7408163, 1166350, 76335, '<td valign="top">Thoughtful.</td>', 'Thoughtful.', '2015-10-05 21:31:08.000000', NULL, 1),
(7408164, 1167231, 76335, '<td valign="top">Fun!</td>', 'Fun!', '2015-10-05 21:31:51.000000', NULL, 1),
(7408165, 1166196, 76335, '<td valign="top">Nice camo!</td>', 'Nice camo!', '2015-10-05 21:32:16.000000', NULL, 1),
(7408166, 1167252, 76335, '<td valign="top">Classical composition, expert arrangement of the arms and body to lead the viewer to her face. Nice softness and tones too.</td>', 'Classical composition, expert arrangement of the arms and body to lead the viewer to her face. Nice softness and tones too.', '2015-10-05 21:34:08.000000', NULL, 1),
(7408167, 1167247, 76335, '<td valign="top">Fun day at the beach.</td>', 'Fun day at the beach.', '2015-10-05 21:35:02.000000', NULL, 1),
(7408168, 1167211, 76335, '<td valign="top">Looks good -- it doesn''t hurt that my fig tree produced fruit for the first time since we got it eight years ago. So I had fresh figs for the first time. I like your arrangement but wish the ice cream weren''t so blown out though. But it does look tasty!</td>', 'Looks good -- it doesn''t hurt that my fig tree produced fruit for the first time since we got it eight years ago. So I had fresh figs for the first time. I like your arrangement but wish the ice cream weren''t so blown out though. But it does look tasty!', '2015-10-05 21:40:05.000000', NULL, 1),
(7408169, 1166973, 76335, '<td valign="top">Every face a story. Nice.</td>', 'Every face a story. Nice.', '2015-10-05 21:40:33.000000', NULL, 1),
