(7409849, 1167215, 101668, '<td valign="top">Magnificent view vantage point light and photo. Lovely</td>', 'Magnificent view vantage point light and photo. Lovely', '2015-10-14 04:01:03.000000', NULL, 0),
(7410270, 1166702, 16148, '<td valign="top">7 from me.  I was a little chintzy.  An image that keeps getting better.  Thanks</td>', '7 from me.  I was a little chintzy.  An image that keeps getting better.  Thanks', '2015-10-16 10:28:07.000000', NULL, 0),
(7411622, 1167300, 25024, '<td valign="top">Hello from the Critique Club<br/> <br/>An appealing image that contributes well to the open challenge<br/> <br/>What a lovely colourful butterfly you''ve captured here in a profile that shows off his remarkable colouring well. You''ve quickly adapted and learnt an important lesson of macro photography, to set your lens to the focussing distance you want and move the camera its by far the most effective technique to use, well done. It''s a fairly minor point but I would prefer it if your composition was more to the right, as it is I feel the left hand edge is a bit close to the main subject, the butterfly, with space to spare on the right of the flower.<br/> <br/>Given the very soft focus background I think you would have been better to use a smaller aperture that would have got the whole of the butterfly in good sharp focus with a little more, though still not distracting, detail in the background. I like your placement of the insects head and the flower head in the brighter part of the background. All in all, its a very competent macro that has the essential elements in good detail.<br/> <br/>Thank you for your entry, Sid</td>', 'Hello from the Critique Club An appealing image that contributes well to the open challenge What a lovely colourful butterfly you''ve captured here in a profile that shows off his remarkable colouring well. You''ve quickly adapted and learnt an important lesson of macro photography, to set your lens to the focussing distance you want and move the camera its by far the most effective technique to use, well done. It''s a fairly minor point but I would prefer it if your composition was more to the right, as it is I feel the left hand edge is a bit close to the main subject, the butterfly, with space to spare on the right of the flower. Given the very soft focus background I think you would have been better to use a smaller aperture that would have got the whole of the butterfly in good sharp focus with a little more, though still not distracting, detail in the background. I like your placement of the insects head and the flower head in the brighter part of the background. All in all, its a very competent macro that has the essential elements in good detail. Thank you for your entry, Sid', '2015-10-22 10:29:33.000000', NULL, 0),
(7412394, 1167273, 23484, '<td valign="top">Very nice catch.</td>', 'Very nice catch.', '2015-10-26 16:35:44.000000', NULL, 0),
(7415007, 1165976, 135744, '<td valign="top">Incredible photo and superb processing. You have captured the magnitude of this building really well.</td>', 'Incredible photo and superb processing. You have captured the magnitude of this building really well.', '2015-11-08 19:15:33.000000', NULL, 0),
(7420252, 1166753, 83313, '<td valign="top">A good shot, but I think what kept it down was the wealth of top notch hummingbird shots that people have seen on DPC before. A high ISO setting resulted in more noise grain to the image than you probably had to have. I generally use ISO 400 as a good general purpose walkabout setting, and in bright light, I use 200. I only take it higher when conditions dictate.</td>', 'A good shot, but I think what kept it down was the wealth of top notch hummingbird shots that people have seen on DPC before. A high ISO setting resulted in more noise grain to the image than you probably had to have. I generally use ISO 400 as a good general purpose walkabout setting, and in bright light, I use 200. I only take it higher when conditions dictate.', '2015-12-03 22:34:57.000000', NULL, 0),
(7433435, 1167212, 117474, '<td valign="top">Impressive that you got in there!</td>', 'Impressive that you got in there!', '2016-01-31 07:04:45.000000', NULL, 0);
